// Read-only catalog quality report. Input must be a complete /entities JSON array,
// not one page, a source YAML file, or an inventory snapshot presented as live state.
const fs = require('node:fs');
const path = require('node:path');

const ref = entity =>
  `${entity.kind}:${entity.metadata.namespace || 'default'}/${
    entity.metadata.name
  }`.toLowerCase();

// Coverage contract (flagship F5): every Kubernetes app must be wired to Argo CD, Kubernetes, Grafana
// dashboards and alerts, logs, a runbook and its source. The values are generated by
// scripts/curate-coverage.cjs; an app that cannot have one needs a reviewed reason in
// catalog/coverage-exceptions.yaml.
const COVERAGE = [
  { id: 'argocd', label: 'Argo CD application', keys: ['argocd/app-name'] },
  { id: 'kubernetes', label: 'Kubernetes resources', keys: ['backstage.io/kubernetes-id', 'backstage.io/kubernetes-label-selector'] },
  { id: 'grafana-dashboard', label: 'Grafana dashboard', keys: ['grafana/dashboard-selector'] },
  { id: 'grafana-alerts', label: 'Grafana alerts', keys: ['grafana/alert-label-selector'] },
  { id: 'logs', label: 'Logs', keys: ['onemind.io/logs-query'] },
  { id: 'runbook', label: 'Runbook', keys: ['onemind.io/recovery-runbook'] },
  { id: 'source', label: 'Source repository', keys: ['github.com/project-slug'] },
];

/** Components that run on the cluster: a catalog "app" with an Argo application or Kubernetes workloads. */
function kubernetesApps(entities) {
  const withWorkloads = new Set();
  for (const entity of entities) {
    const parent = entity.spec?.subcomponentOf;
    if (entity.kind?.toLowerCase() === 'component' && typeof parent === 'string') withWorkloads.add(parent.toLowerCase());
  }
  return entities.filter(entity => {
    if (entity.kind?.toLowerCase() !== 'component') return false;
    if (entity.metadata.labels?.['onemind.io/catalog-role'] !== 'app') return false;
    return !!entity.metadata.annotations?.['argocd/app-name'] || withWorkloads.has(ref(entity));
  });
}

function auditCoverage(entities, exceptions = []) {
  const apps = kubernetesApps(entities);
  const known = new Set(COVERAGE.map(c => c.id));
  const appRefs = new Set(apps.map(ref));
  const invalidExceptions = [];
  const excepted = new Map();
  for (const item of exceptions) {
    const app = typeof item?.app === 'string' ? item.app.toLowerCase() : '';
    if (!app || !known.has(item?.capability) || typeof item?.reason !== 'string' || item.reason.trim().length < 20)
      invalidExceptions.push({ ...item, problem: 'needs an app, a known capability and a reason of at least 20 characters' });
    else excepted.set(`${app}\u0000${item.capability}`, item);
  }
  const missing = [], exceptedFound = [];
  const byCapability = Object.fromEntries(COVERAGE.map(c => [c.id, { covered: 0, excepted: 0, missing: 0 }]));
  const used = new Set();
  for (const app of apps) {
    const annotations = app.metadata.annotations || {};
    for (const capability of COVERAGE) {
      const present = capability.keys.some(key => annotations[key]);
      const id = `${ref(app)}\u0000${capability.id}`;
      if (present) { byCapability[capability.id].covered++; continue; }
      if (excepted.has(id)) { used.add(id); byCapability[capability.id].excepted++; exceptedFound.push({ app: ref(app), capability: capability.id }); continue; }
      byCapability[capability.id].missing++;
      missing.push({ app: ref(app), capability: capability.id });
    }
  }
  // An exception for something that is now present, or for an app that is gone, must be deleted.
  const staleExceptions = [...excepted.entries()].filter(([id, item]) => !used.has(id)).map(([, item]) => ({ app: item.app, capability: item.capability, reason: appRefs.has(item.app.toLowerCase()) ? 'annotation is now present' : 'not a Kubernetes app in the catalog' }));
  const argoApplications = new Set();
  for (const app of apps) {
    const a = app.metadata.annotations || {};
    for (const name of [a['argocd/app-name'], ...(a['onemind.io/argocd-apps'] || '').split(',')]) if (name) argoApplications.add(name.trim());
  }
  return {
    scope: 'Annotation presence on catalog Components; not proof that the linked dashboard, selector or query returns data',
    kubernetesApps: apps.length,
    argoApplicationsLinked: argoApplications.size,
    byCapability,
    fullyCovered: apps.filter(app => COVERAGE.every(c => c.keys.some(key => app.metadata.annotations?.[key]))).length,
    missing,
    excepted: exceptedFound,
    staleExceptions,
    invalidExceptions,
  };
}

function loadCoverageExceptions(file = process.env.ONEMIND_COVERAGE_EXCEPTIONS || path.join(__dirname, '..', 'catalog', 'coverage-exceptions.yaml')) {
  if (!fs.existsSync(file)) return [];
  const doc = require('yaml').parse(fs.readFileSync(file, 'utf8'));
  return Array.isArray(doc?.exceptions) ? doc.exceptions : [];
}

function auditCatalog(entities, now = new Date(), staleDays = 7, exceptions = []) {
  if (
    !Array.isArray(entities) ||
    !Number.isFinite(now.getTime()) ||
    !(staleDays > 0)
  ) {
    throw new Error(
      'Expected a complete entity array, valid observation time and positive stale-days',
    );
  }
  const identities = new Set();
  const duplicateRefs = new Set();
  const kinds = {};
  for (const entity of entities) {
    if (!entity?.kind || !entity.metadata?.name)
      throw new Error('Invalid catalog entity');
    const id = ref(entity);
    if (identities.has(id)) duplicateRefs.add(id);
    identities.add(id);
    kinds[entity.kind] = (kinds[entity.kind] || 0) + 1;
  }
  const missingRelations = new Map();
  const launcherTargets = new Map();
  const staleInventory = [],
    invalidInventoryDates = [],
    reportedErrors = [],
    orphans = [];
  for (const entity of entities) {
    const id = ref(entity),
      annotations = entity.metadata.annotations || {};
    for (const relation of entity.relations || []) {
      const target = relation.targetRef?.toLowerCase();
      if (target && !identities.has(target)) {
        if (!missingRelations.has(target))
          missingRelations.set(target, new Set());
        missingRelations.get(target).add(id);
      }
    }
    const observedAt =
      annotations['onemind.io/inventory-observed-at'] ||
      annotations['onemind.io/observed-at'];
    if (observedAt) {
      const timestamp = Date.parse(observedAt);
      if (!Number.isFinite(timestamp) || timestamp > now.getTime())
        invalidInventoryDates.push(id);
      else if (now.getTime() - timestamp > staleDays * 86400000)
        staleInventory.push({ ref: id, observedAt });
    }
    if (annotations['backstage.io/orphan'] === 'true') orphans.push(id);
    if (
      entity.status?.items?.some(item =>
        ['error', 'warning'].includes(item.level),
      )
    )
      reportedErrors.push(id);
    if (entity.kind.toLowerCase() !== 'component') continue;
    const launcher =
      annotations['onemind.io/launcher-url'] ||
      entity.metadata.links?.find(link => link.title === 'Open application')
        ?.url;
    if (launcher) {
      if (!launcherTargets.has(launcher))
        launcherTargets.set(launcher, new Set());
      launcherTargets.get(launcher).add(id);
    }
  }
  return {
    auditedAt: now.toISOString(),
    scope:
      'Catalog metadata only; not service health, link reachability, deployment readiness or permission verification',
    entityCount: entities.length,
    kinds,
    duplicateRefs: [...duplicateRefs].sort(),
    missingRelations: [...missingRelations].map(([target, sources]) => ({
      target,
      sources: [...sources].sort(),
    })),
    // Do not print URLs: they may contain personal paths, signed queries or fragments.
    sharedLauncherCandidates: [...launcherTargets.values()]
      .filter(ids => ids.size > 1)
      .map(ids => [...ids].sort()),
    staleAfterDays: staleDays,
    staleInventory,
    invalidInventoryDates,
    reportedErrors,
    orphans,
    coverage: auditCoverage(entities, exceptions),
    note: 'Shared launchers are review candidates, not proof of duplicate services. Missing targets may be permission-filtered; confirm against an authorized complete view. Never fabricate observations or delete entities automatically.',
  };
}

if (require.main === module) {
  try {
    const file = process.argv[2];
    if (!file || process.argv.length !== 3)
      throw new Error(
        'Usage: node scripts/audit-catalog.cjs <complete-entities.json|->',
      );
    const report = auditCatalog(
      JSON.parse(fs.readFileSync(file === '-' ? 0 : file, 'utf8')),
      new Date(),
      7,
      loadCoverageExceptions(),
    );
    console.log(JSON.stringify(report, null, 2));
    // Metadata errors gate acceptance; overlap/freshness require explicit review.
    if (
      report.duplicateRefs.length ||
      report.missingRelations.length ||
      report.reportedErrors.length ||
      report.orphans.length ||
      report.invalidInventoryDates.length ||
      report.coverage.missing.length ||
      report.coverage.invalidExceptions.length ||
      report.coverage.staleExceptions.length
    )
      process.exitCode = 1;
  } catch (error) {
    console.error(error.message);
    process.exitCode = 2;
  }
}
module.exports = { auditCatalog, auditCoverage, kubernetesApps, loadCoverageExceptions, COVERAGE };
